const meterHtml=`<div class="sw-meter" role="list" aria-label="SNS 운영 숫자">${meter.map(([label,n,view,tone])=>`<button type="button" role="listitem" data-sw-action="view" data-value="${view}"${tone?` data-tone="${tone}"`:''}><span>${label}</span><strong>${n}</strong></button>`).join('')}</div>`;
let n=0;const no=()=>String(++n).padStart(2,'0'),busy=attention.length>0;
const A=()=>`<section class="sw-block" data-sw-block="attention">${snswSection(no(),'먼저 확인할 일',{count:snswSummary('jobs','attention',attention.length),action:snswSummary('jobs','attention',attention.length)?snswButton('발행 대기열에서 보기','view','queue'):''})}${attention.length?`<div class="sw-stack">${attention.slice(0,5).map((j,i)=>snswJobCard(j,{brief:true,lead:i===0})).join('')}</div>${snswSummary('jobs','attention',attention.length)>attention.length?`<button type="button" class="sw-more-link" data-sw-action="view" data-value="queue">그 밖에 ${snswSummary('jobs','attention',attention.length)-attention.length}건 더 보기</button>`:''}`:snswEmpty('확인할 발행 문제가 없어요','실패·결과 불명확·수동 마무리가 생기면 여기에 먼저 모여요.','ok')}</section>`;
