  const changedScope=!!socialRecoveryState.scopeId&&socialRecoveryState.scopeId!==recovery.scopeId;
  if(changedScope){
    snswRecoveryReset();socialWorkspaceState.upload?.abort?.();socialWorkspaceState.download?.abort?.();
    Object.assign(socialWorkspaceState,{epoch:socialWorkspaceState.epoch+1,request:socialWorkspaceState.request+1,loading:false,busy:false,draft:snswBlank(),dirty:false,editId:'',pending:null,previewChannel:'',bulkText:'',bulkPreview:null,movePreview:null,selectedJobs:[],forms:{},upload:null,download:null,uploadProgress:0,error:'',notice:''});
  }
  socialRecoveryState.scopeId=recovery.scopeId;socialRecoveryState.localKey='synk.social.recovery.v1:'+recovery.scopeId+':'+state.user.id;
  if(changedScope)snswRender();
  const guard=snswGuard(),generation=socialRecoveryState.generation,scopeId=recovery.scopeId,checking=++socialRecoveryState.checking;
  const alive=()=>snswAlive(guard)&&generation===socialRecoveryState.generation&&scopeId===socialRecoveryState.scopeId&&checking===socialRecoveryState.checking;
  let drafts=snswRecoveryDrafts(recovery,alive);if(typeof drafts?.then==='function')drafts=await drafts;if(!drafts)return;
  const merged=new Map(drafts.map(r=>[r.draftKey,r]));
