  if(!snswWritable())return true;
  if(kind==='reply-reconcile'){await snswMutate('inbox/reply/reconcile',{attemptId:form.dataset.id,remoteReplyId:d.remoteReplyId},'SNS의 실제 답장 기록을 확인했어요.',r=>{if(r.attempt?.inboxId)socialWorkspaceState.forms.replyUncertain=snswArray(socialWorkspaceState.forms.replyUncertain).filter(pending=>pending.inboxId!==r.attempt.inboxId);});return true;}
  if(kind==='capacity-preview'){await snswMutate('capacity/preview',{jobIds:snswArray(socialWorkspaceState.forms.capacitySelected),includeFixedJobIds:snswArray(socialWorkspaceState.forms.capacityFixed).filter(id=>snswArray(socialWorkspaceState.forms.capacitySelected).includes(id)),maxShiftHours:Number(d.maxShiftHours)},'예약 시각의 변경 전후를 확인하세요.',r=>{socialWorkspaceState.forms.capacityPreview=r;});return true;}
  if(kind==='reply-preview'){const item=snswRows('inbox').find(i=>i.id===form.dataset.id),permission=snswArray(socialWorkspaceState.data?.replies?.items).find(r=>r.inboxId===item?.id);if(!item||!permission?.canReply||['preparing','submitting','unknown'].includes(permission.latestAttempt?.status)||snswReplyUncertain(item.id))return true;if(permission.observedReplyAcknowledgmentKey&&d.observedReplyAcknowledgmentKey!==permission.observedReplyAcknowledgmentKey){socialWorkspaceState.error='SNS에 이미 있는 답장을 확인하고 추가 답장 확인란을 선택해 주세요.';snswRender();return true;}delete socialWorkspaceState.forms.replyPreview;await snswFourRead('inbox/reply/preview',{inboxId:item.id,revision:item.revision,text:d.text,...(permission.observedReplyAcknowledgmentKey?{observedReplyAcknowledgmentKey:d.observedReplyAcknowledgmentKey}:{})},async r=>{const acknowledgmentKey=r.preview.observedReply===null?null:permission.observedReplyAcknowledgmentKey||null;socialWorkspaceState.forms.replyPreview={...r,observedReplyAcknowledgmentKey:acknowledgmentKey};socialWorkspaceState.forms['reply-preview:'+item.id]={text:r.preview.text,...(acknowledgmentKey?{observedReplyAcknowledgmentKey:acknowledgmentKey}:{})};await snswLoad();});return true;}
  if(kind==='copy-insights-template'){const proposal=socialWorkspaceState.forms.copyTemplate;if(!proposal)return true;await snswMutate('templates',{name:d.name,description:d.description,post:proposal.post},'선택한 게시 문구를 템플릿으로 저장했어요. 승인과 예약은 별도로 진행하세요.',()=>{delete socialWorkspaceState.forms.copyTemplate;});return true;}
