function snswFourInput(event){if(!snswActive()||socialWorkspaceState.busy||!snswWritable())return;const target=event.target,ds=target.dataset||{};if(ds.swReplyText||ds.swReplyAck){delete socialWorkspaceState.forms.replyPreview;target.closest?.('[data-sw-reply]')?.querySelector?.('[data-sw-reply-confirm]')?.remove?.();}if(event.type!=='change')return;const kind=ds.swCapacitySelect?'capacitySelected':ds.swCapacityFixed?'capacityFixed':'',id=ds.swCapacitySelect||ds.swCapacityFixed;if(kind){const current=snswArray(socialWorkspaceState.forms[kind]);socialWorkspaceState.forms[kind]=target.checked?[...new Set([...current,id])]:current.filter(v=>v!==id);if(kind==='capacitySelected'&&!target.checked)socialWorkspaceState.forms.capacityFixed=snswArray(socialWorkspaceState.forms.capacityFixed).filter(v=>v!==id);delete socialWorkspaceState.forms.capacityPreview;snswRender();}}
document.addEventListener('input',snswFourInput);document.addEventListener('change',snswFourInput);

function snswReplyUncertain(inboxId){return snswArray(socialWorkspaceState.forms.replyUncertain).some(r=>r.inboxId===inboxId);}
function snswReplyProgress(inboxId,latest){const pending=snswArray(socialWorkspaceState.forms.replyUncertain).find(r=>r.inboxId===inboxId);if(!pending||['sent','failed','unknown'].includes(latest?.status))return '';return pending.sending?'<p class="sw-note" role="status">답장을 전송하고 있어요. 응답을 기다리는 동안 다시 보내지 않아요.</p>':'<p class="sw-warning">전송 응답을 받지 못했어요. 같은 답장은 다시 보내지 않아요. 새로고침한 뒤 SNS 원문을 확인하세요.</p>';}
function snswReplyStopWaiting(inboxId,attemptId){const pending=snswArray(socialWorkspaceState.forms.replyUncertain).find(r=>r.inboxId===inboxId&&r.attemptId===attemptId);if(pending)pending.sending=false;}
function snswReplyPreviewCurrent(prepared,data=socialWorkspaceState.data){const preview=prepared?.preview,item=snswArray(data?.inbox).find(row=>row.id===preview?.inboxId),permission=snswArray(data?.replies?.items).find(row=>row.inboxId===preview?.inboxId),channel=snswArray(data?.channels).find(row=>row.id===item?.channelId);return Boolean(preview&&item&&channel&&channel.canEdit!==false&&permission?.canReply&&!['preparing','submitting','unknown'].includes(permission.latestAttempt?.status)&&Number.isInteger(preview.revision)&&preview.revision===item.revision&&preview.account?.channelId===item.channelId&&(prepared.observedReplyAcknowledgmentKey||null)===(permission.observedReplyAcknowledgmentKey||null));}
function snswFourAccept(data){for(const permission of snswArray(data?.replies?.items)){const draft=socialWorkspaceState.forms['reply-preview:'+permission.inboxId];if(draft?.observedReplyAcknowledgmentKey!==permission.observedReplyAcknowledgmentKey&&draft)delete draft.observedReplyAcknowledgmentKey;}if(socialWorkspaceState.forms.replyPreview&&!snswReplyPreviewCurrent(socialWorkspaceState.forms.replyPreview,data))delete socialWorkspaceState.forms.replyPreview;const attempts=snswArray(data?.replies?.attempts);socialWorkspaceState.forms.replyUncertain=snswArray(socialWorkspaceState.forms.replyUncertain).filter(pending=>!attempts.some(a=>a.id===pending.attemptId&&a.inboxId===pending.inboxId&&['sent','failed','unknown'].includes(a.status)));}

function snswCopySource(source){return {'api:instagram':'Instagram API','api:facebook':'Facebook API','api:youtube':'YouTube API',manual:'직접 기록','first-party:redirect':'추적 링크 이동','first-party:browser':'사이트 신고','first-party:verified':'사이트 서버 확인'}[source]||source||'미확인';}

// Setup and follow-up selection retain authored input across local rerenders.
document.addEventListener('change',event=>{if(!snswActive())return;const target=event.target;if(socialWorkspaceState.busy){const busyForm=target?.closest?.('[data-sw-form="followup"]');if(busyForm)socialWorkspaceState.forms['followup:'+busyForm.dataset.id]={...socialWorkspaceState.forms['followup:'+busyForm.dataset.id],...Object.fromEntries(new FormData(busyForm)),revision:Number(busyForm.dataset.revision)};return;}if(target?.hasAttribute?.('data-sw-setup-channel')){socialWorkspaceState.forms.setupChannel=target.value;snswRender();return;}const form=target?.closest?.('[data-sw-form="followup"]');if(form){socialWorkspaceState.forms['followup:'+form.dataset.id]={...Object.fromEntries(new FormData(form)),revision:Number(form.dataset.revision)};if(target.hasAttribute?.('data-sw-followup-room')){socialWorkspaceState.forms['followup:'+form.dataset.id].assigneeId='';snswRender();}}});

document.addEventListener('click',event=>{const s=event.target.closest?.('.sw-meta-fold>summary');if(s&&typeof socialWorkspaceState!=='undefined')socialWorkspaceState.forms.metaOpen=!s.parentElement.open;},true);
document.addEventListener('click',event=>{for(const d of document.querySelectorAll('.sw-workspace details.sw-menu[open],.sw-workspace details.sw-cal-tray[open]'))if(!d.contains(event.target))d.open=false;});document.addEventListener('keydown',event=>{if(event.key!=='Escape')return;for(const d of document.querySelectorAll('.sw-workspace details.sw-menu[open],.sw-workspace details.sw-cal-tray[open]')){d.open=false;d.querySelector('summary')?.focus();}});
